import{_ as a,o as t,c as i,ag as o}from"./chunks/framework.BwSLX4ak.js";const u=JSON.parse('{"title":"Troubleshooting","description":"","frontmatter":{},"headers":[],"relativePath":"en/shitbot/troubleshooting.md","filePath":"en/shitbot/troubleshooting.md"}'),s={name:"en/shitbot/troubleshooting.md"};function n(l,e,r,d,c,h){return t(),i("div",null,[...e[0]||(e[0]=[o(`<h1 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h1><p>Start with:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/shitbot status</span></span></code></pre></div><p>Record the platform, server version, Java version, and complete console logs around the problem.</p><h2 id="onebot-stays-disconnected" tabindex="-1">OneBot stays disconnected <a class="header-anchor" href="#onebot-stays-disconnected" aria-label="Permalink to &quot;OneBot stays disconnected&quot;">​</a></h2><p>Check that:</p><ol><li>OneBot v11 forward WebSocket is enabled.</li><li>The protocol, address, and port in <code>onebot.websocket-url</code> are correct.</li><li><code>access-token</code> matches OneBot.</li><li><code>127.0.0.1</code> refers to the machine running ShitBot, not a different OneBot host.</li><li>Cross-host connections use <code>wss://</code>; remote <code>ws://</code> is rejected by default.</li><li>Java trusts the <code>wss://</code> certificate.</li><li>The firewall permits the Minecraft instance to connect to OneBot.</li><li>The OneBot implementation supports v11 forward WebSocket.</li></ol><h2 id="qq-commands-get-no-reply" tabindex="-1">QQ commands get no reply <a class="header-anchor" href="#qq-commands-get-no-reply" aria-label="Permalink to &quot;QQ commands get no reply&quot;">​</a></h2><p>Check that:</p><ul><li>The group is in <code>onebot.allowed-group-ids</code>, or <code>allow-all-groups</code> is deliberately enabled.</li><li>OneBot reports a group message event.</li><li><code>onebot.commands.&lt;feature&gt;.enabled</code> is on.</li><li>The input matches an alias in the selected language file. English aliases require <code>language: &quot;en_US&quot;</code>.</li><li>The command is not on cooldown.</li><li>The bot can send group messages and images.</li><li><code>/shitbot status</code> reports a healthy database and OneBot connection.</li></ul><h2 id="qq-or-mc-does-not-forward" tabindex="-1">#qq or #mc does not forward <a class="header-anchor" href="#qq-or-mc-does-not-forward" aria-label="Permalink to &quot;#qq or #mc does not forward&quot;">​</a></h2><p>Each direction has its own switch:</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">forwarding</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  game-to-group</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    enabled</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  group-to-game</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    enabled</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span></span></code></pre></div><p>With <code>require-prefix: true</code>, include the entire prefix, including its trailing space. Game-to-QQ destinations come from <code>allowed-group-ids</code>.</p><h2 id="a-bound-player-is-still-blocked" tabindex="-1">A bound player is still blocked <a class="header-anchor" href="#a-bound-player-is-still-blocked" aria-label="Permalink to &quot;A bound player is still blocked&quot;">​</a></h2><p>Check that:</p><ul><li>The Minecraft ID in the QQ command exactly matches the actual name, including case.</li><li>The binding command uses the latest code generated for this login attempt.</li><li>The code has not expired.</li><li>The QQ account has not exceeded <code>maximum-ids-per-qq</code>.</li><li>The proxy and backends share the same MySQL database.</li><li>The player&#39;s binding exists in the database.</li><li>Database charset, collation, and schema have not been manually altered.</li></ul><h2 id="database-connection-fails" tabindex="-1">Database connection fails <a class="header-anchor" href="#database-connection-fails" aria-label="Permalink to &quot;Database connection fails&quot;">​</a></h2><p>For SQLite:</p><ul><li>The plugin data directory is writable.</li><li>No other process is opening the shared file.</li><li>Enough disk space is available.</li></ul><p>For MySQL:</p><ul><li>Address, port, database, username, and password are correct.</li><li>The account has permissions on the target database.</li><li>Remote connections use <code>sslMode=VERIFY_IDENTITY</code>.</li><li>Java trusts the database certificate.</li><li>The server can reach <code>repo.maven.apache.org</code>, or a compatible JDBC driver is available.</li><li>The firewall and MySQL bind address permit the connection.</li></ul><h2 id="the-proxy-reports-no-available-backend" tabindex="-1">The proxy reports no available backend <a class="header-anchor" href="#the-proxy-reports-no-available-backend" aria-label="Permalink to &quot;The proxy reports no available backend&quot;">​</a></h2><p>Check that:</p><ol><li>Backend Spigot uses <code>deployment.role: &quot;backend&quot;</code>.</li><li>Its listener is enabled.</li><li>The endpoint name matches the backend&#39;s <code>server-name</code>.</li><li>Address, port, and token agree on both sides.</li><li>The token has at least 16 characters.</li><li><code>allowed-proxy-addresses</code> contains the actual proxy IP.</li><li>Cross-machine connections use TLS or an explicitly allowed encrypted tunnel.</li><li>The firewall allows only the proxy to access the listener.</li><li>Proxy and backend system clocks are correct.</li></ol><p>See <a href="/docs/en/shitbot/proxy-backend.html">Proxies and backend servers</a>.</p><h2 id="a-shortcut-reports-no-permission" tabindex="-1">A shortcut reports no permission <a class="header-anchor" href="#a-shortcut-reports-no-permission" aria-label="Permalink to &quot;A shortcut reports no permission&quot;">​</a></h2><ul><li>The sender must have a bound character unless <code>allow-unbound</code> is explicitly enabled.</li><li>The character must have the shortcut&#39;s <code>permission</code>.</li><li>Offline checks need LuckPerms, Vault, or available offline OP information.</li><li>Proxy-local and backend commands use different platform permission systems.</li><li>An empty <code>permission</code> skips game permission checks; it does not automatically allow unbound QQ accounts.</li></ul><h2 id="inventory-snapshots-or-textures-are-missing" tabindex="-1">Inventory snapshots or textures are missing <a class="header-anchor" href="#inventory-snapshots-or-textures-are-missing" aria-label="Permalink to &quot;Inventory snapshots or textures are missing&quot;">​</a></h2><ul><li>The player must have joined a backend responsible for snapshots at least once.</li><li><code>inventory.enabled</code> must be on.</li><li>All network instances must share MySQL.</li><li>The renderer must be able to read resource packs, client JARs, or exported icons.</li><li>Old snapshots may need a new login to capture new fields and player head data.</li></ul><p>See <a href="/docs/en/shitbot/inventory.html">Inventory queries and textures</a>.</p><h2 id="chinese-text-in-images-is-broken" tabindex="-1">Chinese text in images is broken <a class="header-anchor" href="#chinese-text-in-images-is-broken" aria-label="Permalink to &quot;Chinese text in images is broken&quot;">​</a></h2><p>Install the fonts selected by <code>image.font-name</code> and <code>inventory.font-name</code>. Linux usually does not include <code>Microsoft YaHei</code>; install a font or select an available Chinese font.</p><h2 id="advanced-templates-fail-to-start" tabindex="-1">Advanced templates fail to start <a class="header-anchor" href="#advanced-templates-fail-to-start" aria-label="Permalink to &quot;Advanced templates fail to start&quot;">​</a></h2><p>First decide whether you need the advanced system. If not, keep <code>custom-image-templates.enabled: false</code> and <code>image.renderer: &quot;java&quot;</code>.</p><p>Otherwise, check that:</p><ul><li><code>image.renderer: &quot;custom&quot;</code> is paired with the advanced-template switch being enabled.</li><li>With <code>debug: true</code>, <code>components/image-renderer/&lt;version&gt;/ShitBotRenderer-&lt;version&gt;.jar</code> exists in the plugin data directory with valid metadata and version. Debug mode does not download it or require <code>.sha256</code> and <code>.sig</code>.</li><li>With <code>debug: false</code>, the release includes the matching renderer JAR, checksum, and signature.</li><li>With <code>debug: false</code>, the server can access GitHub release download hosts.</li><li>With <code>debug: false</code>, <code>components/image-renderer/&lt;version&gt;/</code> is writable and cached files have not been manually replaced.</li><li>Download size, assets, canvas, pixels, layers, loops, rendering time, and queues remain within limits.</li><li>The template is published and its ID in <code>image.custom-template</code> or the group command is correct.</li><li>Remote images are enabled. If an old configuration still has <code>custom-image-templates.remote-images.enabled: false</code>, change it to <code>true</code> and reload before using HTTPS avatars/images. The default online template also needs <code>image.avatar.enabled: true</code> to supply avatar URLs.</li><li>PAPI templates have PlaceholderAPI on the Spigot backend, an online player, and correct endpoint/<code>target-server</code> settings.</li></ul><p>If the editor does not open, enable <code>editor.enabled: true</code> and run <code>/shitbot editor</code> again for an unused login URL. Reverse proxies must use HTTPS and preserve the original <code>Host</code>; keep the internal listener on loopback.</p><h2 id="reload-fails" tabindex="-1">Reload fails <a class="header-anchor" href="#reload-fails" aria-label="Permalink to &quot;Reload fails&quot;">​</a></h2><p>The old runtime stays active when <code>/shitbot reload</code> fails. Find the earliest configuration or connection error in the console, fix it, and reload again.</p><p>Restart directly after:</p><ul><li>Replacing the plugin JAR.</li><li>Changing Java or server software.</li><li>Replacing TLS key stores or trust stores.</li><li>Changing underlying networking, firewall, or database services.</li></ul><h2 id="still-unresolved" tabindex="-1">Still unresolved <a class="header-anchor" href="#still-unresolved" aria-label="Permalink to &quot;Still unresolved&quot;">​</a></h2><p>Open a <a href="https://github.com/hutuyee/ShitBot/issues" target="_blank" rel="noreferrer">GitHub issue</a> with:</p><ul><li>ShitBot version.</li><li>Platform and server version.</li><li>Java version.</li><li>Standalone, proxy, or proxy/backend deployment.</li><li>Logs with tokens, passwords, database addresses, and private player data removed.</li><li>Reliable reproduction steps.</li></ul><p>Do not ask for ShitBot support in LLBot groups.</p>`,46)])])}const m=a(s,[["render",n]]);export{u as __pageData,m as default};
